from taf.gnb.oam.coam.cu.interfaces.cuoam21b import CUOAM21B
from taf.gnb.oam.coam.cu.interfaces.cuoam22r4 import CUOAM22R4
from taf.gnb.oam.coam.cu.interfaces.cuoam23r1 import CUOAM23R1
from taf.gnb.oam.coam.cu.interfaces.cuoam23r2 import CUOAM23R2
from taf.gnb.oam.coam.cu.interfaces.cuoam23r3 import CUOAM23R3
from taf.gnb.oam.coam.cu.interfaces.cuoam24r1 import CUOAM24R1
from taf.gnb.oam.coam.cu.interfaces.cuoam24r2 import CUOAM24R2
from taf.gnb.oam.coam.cu.interfaces.cuoam24r3 import CUOAM24R3
from taf.gnb.oam.coam.cu.interfaces.cuoam25r1 import CUOAM25R1
