class ConnectionDetails:
    def __init__(self, host, port, username, password, secure=False, login_disabled=False, timeout=None, use_m2m=False,
                 alias="default", read_only=False, update_expired_password=True):
        """
        Initialize connection details for the CU.

        :param host: The hostname or IP address of the CU.
        :param port: The port number for the CU.
        :param username: The username for authentication.
        :param password: The password for authentication.
        :param secure: Whether to use HTTPS (default is False).
        :param login_disabled: Whether login is disabled (default is False).
        :param timeout: Timeout for the connection in seconds (default is None).
        :param use_m2m: Whether to use machine-to-machine
                        authentication (default is False).
        :param alias: An alias for the connection (default is "default").
        :param read_only: Whether the connection is read-only (default is False).
        :param update_expired_password: Whether to update expired passwords
                                        automatically (default is True).
        """
        self.protocol = 'http://'
        self.host = host
        self.port = port
        self.secure = secure
        self.username = username
        self.password = password
        self.login_disabled = login_disabled
        self.timeout = int(timeout) if timeout else None
        self.use_m2m = use_m2m
        self.access_token = None
        self.alias = f"{alias}_{id(self)}"
        self.read_only = read_only
        self.update_expired_password = update_expired_password

        if self.secure is True:
            self.protocol = 'https://'
        self.base_url = f"{self.protocol}{ConnectionDetails.normalize_host_for_base_url(self.host)}:{self.port}"

    @staticmethod
    def normalize_host_for_base_url(host):
        """
        Normalize the host for use in a base URL.
        If the host is an IPv6 address, it will be enclosed in square brackets.
        If it is an IPv4 address or a hostname, it will be returned as is.

        :param host: The host to normalize.

        :returns: Normalized host string suitable for use in a base URL.
        :rtype: str
        """
        host = host.rstrip("]").lstrip("[")
        try:
            if isinstance(ip_address(u(str(host))), IPv6Address):
                return f'[{host}]'
            else:
                return host
        except (ValueError, TypeError):
            return host

    def make_configuration_host(self, original_endpoint):
        """
        Adjust the original endpoint to use the base URL and remove any localhost references.

        :param original_endpoint: The original endpoint URL that may contain 'localhost'.

        :returns: A modified endpoint URL that uses the base URL and removes 'localhost'.
        :rtype: str
        """
        endpoint_match = re.match(r'^http.*localhost', original_endpoint)
        endpoint = original_endpoint.replace(endpoint_match.group(), '')
        original_endpoint = f'{self.base_url}{endpoint}'
        return original_endpoint


class CUProvider:
    DEFAULT = 'cuoam_26r1'

    _supported_cus = {
        'cuoam_19b': CUOAM19B,
        'cuoam_21b': CUOAM21B,
        'cuoam_22r4': CUOAM22R4,
        'cuoam_23r1': CUOAM23R1,
        'cuoam_23r2': CUOAM23R2,
        'cuoam_23r3': CUOAM23R3,
        'cuoam_24r1': CUOAM24R1,
        'cuoam_24r2': CUOAM24R2,
        'cuoam_24r3': CUOAM24R3,
        'cuoam_25r1': CUOAM25R1,
        'cuoam_25r2': CUOAM25R2,
        'cuoam_25r3': CUOAM25R3,
        'cuoam_26r1': CUOAM26R1,
    }

    @classmethod
    def create_cu(cls, host, port, username, password, cu_version='cuoam_26r1', secure=False, login_disabled=False,
                  timeout=None, use_m2m=False, alias="default", read_only=False, update_expired_password=True):
        """
        Create a CU instance based on the specified version.

        :param host: The hostname or IP address of the CU.
        :param port: The port number for the CU.
        :param username: The username for authentication.
        :param password: The password for authentication.
        :param cu_version: The version of the CU to create (default is 'cuoam_26r1').
        :param secure: Whether to use HTTPS (default is False).
        :param login_disabled: Whether login is disabled (default is False).
        :param timeout: Timeout for the connection in seconds (default is None).
        :param use_m2m: Whether to use machine-to-machine authentication (default is False).
        :param alias: An alias for the connection (default is "default").
        :param read_only: Whether the connection is read-only (default is False).
        :param update_expired_password: Whether to update expired passwords automatically (default is True).

        :raises CuVersionNotSupported: If the specified CU version is not supported.

        :returns: An instance of the CU corresponding to the specified version.
        """
        if cu_version in CUProvider._supported_cus:

            if cu_version != CUProvider.DEFAULT:
                log_warning(f"You are using cu_version={cu_version}, which is different from the latest version - "
                            f"{CUProvider.DEFAULT}. Please bear in mind that in order to have access to the latest library "
                            f"updates the default value of cu_version should be used.")

            con_details = ConnectionDetails(host=host,
                                            port=port,
                                            username=username,
                                            password=password, secure=secure,
                                            login_disabled=login_disabled,
                                            timeout=timeout,
                                            use_m2m=use_m2m,
                                            alias=alias,
                                            read_only=read_only,
                                            update_expired_password=update_expired_password)

            return CUProvider._supported_cus[cu_version](con_details=con_details)

        raise CuVersionNotSupported(f'Version {cu_version} of cu is not supported')
